struct GlobalArgs {
    threads: u64,
    format: Format,
    apparent_size: bool,
    count_hard_links: bool,
    stay_on_filesystem: bool,
    ignore_dirs: Vec<PathBuf>,
    log_file: Option<PathBuf>,
    input: Vec<String>,
}

impl GlobalArgs {
    fn from_matches(m: &clap::ArgMatches) -> Self {
        let threads = *m.get_one::<u64>("threads").unwrap_or(&0);
        let format_str = m.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("binary");
        let format = Format::from_str(format_str);
        let apparent_size = m.get_flag("apparent-size");
        let count_hard_links = m.get_flag("count-hard-links");
        let stay_on_filesystem = m.get_flag("stay-on-filesystem");
        let ignore_dirs: Vec<PathBuf> = m.get_many::<String>("ignore-dirs").map(|v| v.map(|s| PathBuf::from(s)).collect()).unwrap_or_default();
        let log_file = m.get_one::<String>("log-file").map(|s| PathBuf::from(s));
        let input: Vec<String> = m.get_many::<String>("INPUT").map(|v| v.cloned().collect()).unwrap_or_default();
        Self { threads, format, apparent_size, count_hard_links, stay_on_filesystem, ignore_dirs, log_file, input }
    }
}

