const ELVISH_COMPLETION: &str = r#"
use builtin;
use str;

set edit:completion:arg-completer[dua] = {|@words|
    fn spaces {|n|
        builtin:repeat $n ' ' | str:join ''
    }
    fn cand {|text desc|
        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc
    }
    var command = 'dua'
    for word $words[1..-1] {
        if (str:has-prefix $word '-') {
            break
        }
        set command = $command';'$word
    }
    var completions = [
        &'dua'= {
            cand -t 'The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread'
            cand --threads 'The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread'
            cand -f 'The format with which to print byte counts'
            cand --format 'The format with which to print byte counts'
            cand -i 'One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path'
            cand --ignore-dirs 'One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path'
            cand --log-file 'Write a log file with debug information, including panics'
            cand -A 'Display apparent size instead of disk usage'
            cand --apparent-size 'Display apparent size instead of disk usage'
            cand -l 'Count hard-linked files each time they are seen'
            cand --count-hard-links 'Count hard-linked files each time they are seen'
            cand -x 'If set, we will not cross filesystems or traverse mount points'
            cand --stay-on-filesystem 'If set, we will not cross filesystems or traverse mount points'
            cand -h 'Print help (see a summary with ''-h'')'
            cand --help 'Print help (see a summary with ''-h'')'
            cand -V 'Print version'
            cand --version 'Print version'
            cand interactive 'Launch the terminal user interface'
            cand aggregate 'Aggregate the consumed space of one or more directories or files'
            cand completions 'Generate shell completions'
            cand help 'Print this message or the help of the given subcommand(s)'
        }
        &'dua;aggregate'= {
            cand --stats 'If set, print additional statistics about the file traversal to stderr'
            cand --no-sort 'If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending'
            cand --no-total 'If set, no total column will be computed for multiple inputs'
            cand -h 'Print help'
            cand --help 'Print help'
        }
        &'dua;completions'= {
            cand -h 'Print help'
            cand --help 'Print help'
            cand bash 'bash'
            cand elvish 'elvish'
            cand fish 'fish'
            cand powershell 'powershell'
            cand zsh 'zsh'
        }
        &'dua;help'= {
            cand aggregate 'Aggregate the consumed space of one or more directories or files'
            cand completions 'Generate shell completions'
            cand help 'Print this message or the help of the given subcommand(s)'
            cand interactive 'Launch the terminal user interface'
        }
        &'dua;interactive'= {
            cand -e 'Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems'
            cand --no-entry-check 'Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems'
            cand -h 'Print help'
            cand --help 'Print help'
        }
    ]
    var add = {|completions|
        var suffix = []
        for cand $completions {
            if (str:has-prefix $cand:text $words[-1]) {
                set suffix = [$@suffix $cand]
            }
        }
        if (==s (count $suffix) 0) {
            edit:complex-candidate $words[-1]
        } else {
            put $@suffix
        }
    }
    if (has-key $completions $command) {
        $add $completions[$command]
    } else {
        edit:complex-candidate $words[-1]
    }
}
