fn run_aggregate(global: &GlobalArgs, inputs: &[String], stats: bool, no_sort: bool, no_total: bool, bin: &str) {
    // Logging
    if let Some(log_path) = &global.log_file {
        if let Ok(mut f) = fs::OpenOptions::new().create(true).append(true).open(log_path) {
            let now = chrono::Local::now().format("%H:%M:%S");
            let _ = writeln!(f, "{} [INFO] dua options=Args {{", now);
            let _ = writeln!(f, "    command: None,");
            let _ = writeln!(f, "    threads: {},", global.threads);
            let fmt_name = match global.format {
                Format::Metric => "Metric",
                Format::Binary => "Binary",
                Format::Bytes => "Bytes",
                Format::Gb => "Gb",
                Format::Gib => "Gib",
                Format::Mb => "Mb",
                Format::Mib => "Mib",
            };
            let _ = writeln!(f, "    format: {},", fmt_name);
            let _ = writeln!(f, "    apparent_size: {},", global.apparent_size);
            let _ = writeln!(f, "    count_hard_links: {},", global.count_hard_links);
            let _ = writeln!(f, "    stay_on_filesystem: {},", global.stay_on_filesystem);
            let _ = writeln!(f, "    ignore_dirs: [");
            for d in &global.ignore_dirs {
                let _ = writeln!(f, "        \"{}\",", d.display());
            }
            let _ = writeln!(f, "    ],");
            if inputs.is_empty() {
                let _ = writeln!(f, "    input: [],");
            } else {
                let _ = writeln!(f, "    input: [");
                for inp in inputs {
                    let _ = writeln!(f, "        \"{}\",", inp);
                }
                let _ = writeln!(f, "    ],");
            }
            if let Some(log) = &global.log_file {
                let _ = writeln!(f, "    log_file: Some(");
                let _ = writeln!(f, "        \"{}\",", log.display());
                let _ = writeln!(f, "    ),");
            } else {
                let _ = writeln!(f, "    log_file: None,");
            }
            let _ = writeln!(f, "}}");
            // Also ignore canonicalized
            // Need canonicalized ignore dirs: we can just list them
            let mut ignore_set: HashSet<String> = HashSet::new();
            for p in &global.ignore_dirs {
                // canonicalize if exists
                if let Ok(c) = fs::canonicalize(p) {
                    ignore_set.insert(c.to_string_lossy().to_string());
                } else {
                    ignore_set.insert(p.to_string_lossy().to_string());
                }
            }
            if !ignore_set.is_empty() {
                let mut vec: Vec<String> = ignore_set.into_iter().collect();
                vec.sort();
