        }
        let mut total = if apparent { meta.len() } else { meta.blocks() * 512 };
        // For disk, dir's own blocks may be 0 for small dirs, but for bigdir 4096 etc.
        // Need to handle ignore inside recursion also?
        let children = match fs::read_dir(path) {
            Ok(r) => r,
            Err(_) => return total,
        };
