#[derive(Debug, Clone, PartialEq, Eq)]
enum Format {
    Metric,
    Binary,
    Bytes,
    Gb,
    Gib,
    Mb,
    Mib,
}

impl Format {
    fn from_str(s: &str) -> Self {
        match s {
            "metric" => Format::Metric,
            "binary" => Format::Binary,
            "bytes" => Format::Bytes,
            "gb" => Format::Gb,
            "gib" => Format::Gib,
            "mb" => Format::Mb,
            "mib" => Format::Mib,
            _ => Format::Binary,
        }
    }
    fn format(&self, size: u64) -> String {
        match self {
            Format::Bytes => format!("{:>10} b ", size),
            Format::Binary => {
                if size <= 1024 {
                    format!("{:>7}   B ", size)
                } else {
                    let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
                    let mut val = size as f64 / 1024.0;
                    let mut idx = 1;
                    while val > 1024.0 && idx < units.len() - 1 {
                        val /= 1024.0;
                        idx += 1;
                    }
                    format!("{:>7.2} {:>3} ", val, units[idx])
                }
            }
            Format::Metric => {
                if size <= 1000 {
                    format!("{:>7}  B ", size)
                } else {
                    let units = ["B", "KB", "MB", "GB", "TB", "PB", "EB"];
                    let mut val = size as f64 / 1000.0;
                    let mut idx = 1;
                    while val > 1000.0 && idx < units.len() - 1 {
                        val /= 1000.0;
                        idx += 1;
                    }
                    format!("{:>7.2} {:>2} ", val, units[idx])
                }
            }
            Format::Mib => {
                let val = size as f64 / (1024.0 * 1024.0);
                format!("{:>8.2} MiB ", val)
            }
            Format::Mb => {
                let val = size as f64 / 1_000_000.0;
                format!("{:>9.2} MB ", val)
            }
            Format::Gib => {
                let val = size as f64 / (1024.0 * 1024.0 * 1024.0);
                format!("{:>6.2} GiB ", val)
            }
            Format::Gb => {
                let val = size as f64 / 1_000_000_000.0;
                format!("{:>6.2} GB ", val)
            }
        }
    }
}

