fn print_completions(shell: &str, bin: &str) {
    let content = match shell {
        "bash" => BASH_COMPLETION,
        "zsh" => ZSH_COMPLETION,
        "fish" => FISH_COMPLETION,
        "elvish" => ELVISH_COMPLETION,
        "powershell" => POWERSHELL_COMPLETION,
        _ => "",
    };
    // For fish/zsh etc, the script contains "dua" as program name, not bin. The observed completions always use "dua" regardless of bin.
    // So we don't replace.
    print!("{}", content);
}

const BASH_COMPLETION: &str = r#"_dua() {
