            opts="-t  -f  -A  -l  -x  -i  --threads  --format  --apparent-size  --count-hard-links  --stay-on-filesystem  --ignore-dirs  --log-file  -h  --help  -V  --version  [INPUT]...  interactive  aggregate  completions  help"
