struct Stats {
    entries_traversed: u64,
    smallest: u64,
    largest: u64,
}

fn list_children(dir: &Path, global: &GlobalArgs, ignore: &HashSet<PathBuf>) -> Vec<PathBuf> {
    let mut children = Vec::new();
    let read = match fs::read_dir(dir) {
        Ok(r) => r,
        Err(_) => return children,
    };
    for entry in read {
        if let Ok(e) = entry {
            let path = e.path();
            // Check ignore
            // For ignore, we need to check if path is under ignore dir (canonical)
            // But ignore is for traversal: if path is inside ignored dir, skip.
            // We can check if any ignore dir is prefix of canonical path?
            // Simplified: if path canonical starts with ignore canonical, skip.
            // But for children listing, we check if child itself is ignored? The docs say ignore dirs are not ignored if passed as input, but if reached as part of traversal.
            // So if dir is /tmp/a and ignore is /tmp/a/b, then child b should be ignored when listing dir's children.
            // So we need to check if child path (canonical if exists, else path) is equal to or under ignore.
            let mut skip = false;
            if let Ok(c) = fs::canonicalize(&path) {
                for ign in ignore {
                    if c == *ign || c.starts_with(ign) {
                        skip = true;
                        break;
                    }
                }
            } else {
                // If can't canonicalize, check raw path
                for ign in ignore {
                    if path == *ign || path.starts_with(ign) {
                        skip = true;
                        break;
                    }
                }
            }
            if skip {
                continue;
            }
            // Check symlink: if child is symlink, we skip for expanded view? But for aggregated we handle differently.
            // For list_children used in expanded view, we should skip symlinks that are not dirs? But earlier we saw dir with symlink file inside was skipped, and dir with symlink dir inside was also skipped? Let's check: earlier dir with symlink file inside: expanded showed only real file, not symlink. Dir with symlink dir inside: we tested dir with symlink dir inside and it was skipped? Actually we tested dir with symlink dir inside and expanded showed only real sub, not link. So we skip all symlinks when listing children for expanded view.
            // But what about traversing for aggregated? For compute_aggregated, we also skip symlinks inside dir traversal.
            if let Ok(md) = fs::symlink_metadata(&path) {
                if md.file_type().is_symlink() {
                    continue;
                }
            }
            // Also skip if stay_on_filesystem and different device?
            // We'll handle later in compute_aggregated, but for list we also need to consider?
            children.push(path);
        }
    }
    children
}

fn compute_aggregated(path: &Path, apparent: bool, count_hard: bool, ignore: &HashSet<PathBuf>, seen: &mut HashSet<(u64,u64)>, stats: &mut Stats, stay_on_fs: bool, parent_dev: Option<u64>) -> u64 {
    // This computes aggregated size for path (file or dir)
    // For dir: size = dir's own size (apparent: len, disk: blocks*512) + sum of children's aggregated (recursive)
    // But for expanded view's total, we used sum children only, not including dir's own. But for aggregated as input, we include dir's own.
    // However this function is used for both cases: when we call compute_aggregated for a child, we want its aggregated size including its own dir size.
    // For file, it's just file size.

    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return 0,
    };
    if meta.file_type().is_symlink() {
        // Should not happen for regular compute, but handle
        return 0;
    }
    if meta.is_dir() {
        // Check stay_on_filesystem: if parent_dev Some and meta.dev() != parent_dev, skip?
        if stay_on_fs {
            if let Some(pdev) = parent_dev {
                if meta.dev() != pdev {
                    return 0;
                }
            }
        }
        let mut total = if apparent { meta.len() } else { meta.blocks() * 512 };
        // For disk, dir's own blocks may be 0 for small dirs, but for bigdir 4096 etc.
        // Need to handle ignore inside recursion also?
        let children = match fs::read_dir(path) {
            Ok(r) => r,
            Err(_) => return total,
        };
        for child in children {
            if let Ok(e) = child {
                let child_path = e.path();
                // Check ignore
                let mut skip = false;
                if let Ok(c) = fs::canonicalize(&child_path) {
                    for ign in ignore {
                        if c == *ign || c.starts_with(ign) {
                            skip = true;
                            break;
                        }
                    }
                } else {
                    for ign in ignore {
                        if child_path == *ign || child_path.starts_with(ign) {
                            skip = true;
                            break;
                        }
                    }
                }
                if skip {
                    continue;
                }
                if let Ok(md) = fs::symlink_metadata(&child_path) {
                    if md.file_type().is_symlink() {
                        continue;
                    }
                    // stay_on_filesystem check for child?
                    if stay_on_fs && md.dev() != meta.dev() {
                        continue;
                    }
                    if md.is_dir() {
                        total += compute_aggregated(&child_path, apparent, count_hard, ignore, seen, stats, stay_on_fs, Some(meta.dev()));
                    } else if md.is_file() {
                        // Check hard link
                        let key = (md.dev(), md.ino());
                        if !count_hard && seen.contains(&key) {
                            // Already counted, size 0
                            // But still need to consider stats? No, smallest/largest should not include duplicate?
                            // Original stats: entries_traversed counts each file seen? For hard links without counting, duplicate should not be counted?
                            // Test earlier: without count, disk for hard links gave one counted, duplicate 0, but entries_traversed? Let's see stats for hard links? Not tested.
                            // We'll assume we do not count duplicate for stats.
                            continue;
                        }
                        if !count_hard {
                            seen.insert(key);
                        }
                        let sz = if apparent { md.len() } else { md.blocks() * 512 };
                        total += sz;
                        stats.entries_traversed += 1;
                        if sz < stats.smallest { stats.smallest = sz; }
                        if sz > stats.largest { stats.largest = sz; }
                    } else {
                        // FIFO etc: size 0? But we earlier saw FIFO counted as 0? For apparent, size 0. For disk, 0.
                        // We'll count as 0 but still traverse?
                        // For FIFO, metadata len 0, blocks 0
                        let sz = if apparent { md.len() } else { md.blocks() * 512 };
                        total += sz;
                        // And stats? Not needed.
                    }
                }
            }
        }
        total
    } else if meta.is_file() {
        let key = (meta.dev(), meta.ino());
        if !count_hard && seen.contains(&key) {
            return 0;
        }
        if !count_hard {
            seen.insert(key);
        }
        let sz = if apparent { meta.len() } else { meta.blocks() * 512 };
        stats.entries_traversed += 1;
        if sz < stats.smallest { stats.smallest = sz; }
        if sz > stats.largest { stats.largest = sz; }
        sz
    } else {
        // Other file types (fifo, socket, etc): treat as 0?
        let sz = if apparent { meta.len() } else { meta.blocks() * 512 };
        // For FIFO earlier, we saw it contributed 0 to total (apparent 0). So 0 is fine.
        sz
    }
}

fn compute_aggregated_symlink_dir(link_path: &Path, apparent: bool, count_hard: bool, ignore: &HashSet<PathBuf>, seen: &mut HashSet<(u64,u64)>, stats: &mut Stats, stay_on_fs: bool) -> u64 {
    // For symlink to dir, aggregated = symlink lstat size + sum of target's children aggregated (recursive)
    // But what about target dir's own size? Should we include target's dir size or symlink's?
    // Earlier deduction: linkdir aggregated = lstat size + file sizes (target's files) + target's subdirs' aggregated?
    // For linkdir with one file 20, target dir size 19, link lstat 26, linkdir aggregated 31 = 26 +5? Actually file 5? Let's see earlier for linkdir with file 5: realdir aggregated 23 = realdir size 18 +5, linkdir aggregated 31 = link lstat 26 +5 =31. So it used symlink lstat + file, not target dir size.
    // For nested case: linkdir pointing to dir with subdir containing file? Would be symlink lstat + subdir aggregated?
    // Let's implement: total = lstat size + children_of_target aggregated (where children are listed from target)

    let link_meta = match fs::symlink_metadata(link_path) {
        Ok(m) => m,
        Err(_) => return 0,
    };
    let target_meta = match fs::metadata(link_path) {
        Ok(m) => m,
        Err(_) => return 0,
    };
    if !target_meta.is_dir() {
        return if apparent { link_meta.len() } else { 0 };
    }
    let mut total = if apparent { link_meta.len() } else { 0 }; // disk for symlink dir? Earlier for symlink to dir disk, aggregated disk was 4096? Let's check: for symlink to file, disk was 0. For symlink to dir disk, what was disk aggregated? For symlink to dir with file, disk aggregated for linkdir vs target: we saw earlier for symsize2: linkdir aggregated disk? We saw linkdir disk? Not tested. Let's test later.
    // For apparent, we use lstat size. For disk, what is symlink's disk usage? Symlink lstat blocks is 0 (we saw blocks 0). So disk aggregated for symlink dir should be 0 + target children disk? But what about target dir's disk? Not included, only symlink's.

    // But earlier for symlink to dir with empty dir: link_empty disk aggregated? We saw link_empty disk aggregated was 0? Actually for empty symlink dir, disk aggregated? Let's check earlier: empty vs link_empty disk aggregated: both were 0? We saw for multiple empty + file disk, link_empty showed 0? For disk, multiple empty + other: link_empty was 0? Let's see: we had empty dir disk: multiple empty + other disk showed empty 0, link_empty 0? For disk, empty and link_empty both 0. So disk for symlink to empty dir is 0, not lstat.

    // So for disk, symlink dir aggregated should be target children disk (no symlink size). For apparent, it's lstat size + children.

    // Let's differentiate: if apparent, total = link_meta.len() + sum children apparent; if disk, total = sum children disk (since symlink blocks 0)

    // Get target path via read_link then canonicalize? But we can just read_dir via link_path (which follows)
    let target_path = link_path; // using link_path for read_dir will follow
    let children = match fs::read_dir(target_path) {
        Ok(r) => r,
        Err(_) => return total,
    };
    for child in children {
        if let Ok(e) = child {
            let child_path = e.path();
            // Need to compute child_path's aggregated, but child_path is under target, not symlink. However for symlink to dir, child paths are like /tmp/symlink/target/file, but we need to compute their aggregated as normal files/dirs.
            // However, for correct ignore handling, we should check ignore for child canonical?

            // Check ignore
            let mut skip = false;
            if let Ok(c) = fs::canonicalize(&child_path) {
                for ign in ignore {
                    if c == *ign || c.starts_with(ign) {
                        skip = true;
                        break;
                    }
                }
            }
            if skip { continue; }
            if let Ok(md) = fs::symlink_metadata(&child_path) {
                if md.file_type().is_symlink() { continue; }
                if stay_on_fs && md.dev() != target_meta.dev() { continue; }
                if md.is_dir() {
                    total += compute_aggregated(&child_path, apparent, count_hard, ignore, seen, stats, stay_on_fs, Some(target_meta.dev()));
                } else if md.is_file() {
                    let key = (md.dev(), md.ino());
                    if !count_hard && seen.contains(&key) { continue; }
                    if !count_hard { seen.insert(key); }
                    let sz = if apparent { md.len() } else { md.blocks()*512 };
                    total += sz;
                    stats.entries_traversed += 1;
                    if sz < stats.smallest { stats.smallest = sz; }
                    if sz > stats.largest { stats.largest = sz; }
                } else {
                    let sz = if apparent { md.len() } else { md.blocks()*512 };
                    total += sz;
                }
            }
        }
    }
    total
}
